class Solution {
public:
    int minUnlockedIndices(vector<int>& nums, vector<int>& locked) {
        int n = nums.size();
        int first2 = n, first3 = n, last1 = -1, last2 = -1;
        for (int i = 0; i < n; ++i) {
            if (nums[i] == 2) first2 = min(first2, i);
            if (nums[i] == 3) first3 = min(first3, i);
            if (nums[i] == 1) last1 = i;
            if (nums[i] == 2) last2 = i;
        }
        if (first3 < last1) return -1;
        vector<char> need(n, 0);
        for (int i = first2; i < last1; ++i) need[i] = 1;
        for (int i = first3; i < last2; ++i) need[i] = 1;
        int ans = 0;
        for (int i = 0; i < n; ++i)
            if (need[i] && locked[i]) ++ans;
        return ans;
    }
};
